var a=233;var i=[{id:`cooking-233-01`,theoryId:233,type:`single_choice`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Which statement describes energy balance?`,ua:`Яке твердження описує енергетичний баланс?`},explanation:{en:`Energy balance concerns intake and expenditure over time, not one meal alone.`,ua:`Енергетичний баланс стосується споживання й витрат енергії в часі, а не лише однієї страви.`},options:[{id:`a`,text:{en:`The total weight of a dinner plate`,ua:`Загальна вага обідньої тарілки`}},{id:`b`,text:{en:`Only the percentage of water in food`,ua:`Лише відсоток води в їжі`}},{id:`c`,text:{en:`Energy intake relative to energy expenditure over time`,ua:`Співвідношення спожитої та витраченої енергії з часом`}}],answer:{optionIds:[`c`]}},{id:`cooking-233-02`,theoryId:233,type:`true_false`,difficulty:`beginner`,safetyCritical:!1,question:{en:`Doubling the serving size usually doubles the calories if the recipe composition stays the same.`,ua:`Подвоєння порції зазвичай подвоює калорійність, якщо склад страви не змінюється.`},explanation:{en:`Energy scales roughly with the quantity of the same prepared food.`,ua:`Енергетична цінність приблизно пропорційна кількості однакової готової страви.`},answer:{value:!0}},{id:`cooking-233-03`,theoryId:233,type:`matching`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`Match portion-planning terms to their meaning.`,ua:`Поєднайте поняття порціонування зі значенням.`},explanation:{en:`These quantities support consistent nutrition calculations.`,ua:`Ці величини допомагають послідовно розраховувати харчову цінність.`},leftItems:[{id:`l1`,text:{en:`Serving size`,ua:`Розмір порції`}},{id:`l2`,text:{en:`Energy density`,ua:`Енергетична щільність`}},{id:`l3`,text:{en:`Total recipe yield`,ua:`Загальний вихід страви`}}],rightItems:[{id:`r3`,text:{en:`Amount produced from a batch`,ua:`Кількість продукту з усієї партії`}},{id:`r2`,text:{en:`Calories per unit mass of food`,ua:`Кількість калорій на одиницю маси їжі`}},{id:`r1`,text:{en:`Quantity used as a reference on a label or plan`,ua:`Кількість, що слугує орієнтиром на етикетці чи в плані`}}],answer:{pairs:[{leftId:`l1`,rightId:`r1`},{leftId:`l2`,rightId:`r2`},{leftId:`l3`,rightId:`r3`}]}},{id:`cooking-233-04`,theoryId:233,type:`decision_scenario`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A soup pot contains 1,200 kcal total and makes six equal portions. What is the energy per portion?`,ua:`Каструля супу містить загалом 1200 ккал і дає шість однакових порцій. Яка калорійність порції?`},explanation:{en:`1,200 ÷ 6 = 200 kcal per portion.`,ua:`1200 ÷ 6 = 200 ккал на порцію.`},options:[{id:`a`,text:{en:`200 kcal`,ua:`200 ккал`}},{id:`b`,text:{en:`1,200 kcal`,ua:`1200 ккал`}},{id:`c`,text:{en:`600 kcal`,ua:`600 ккал`}}],answer:{optionIds:[`a`]}},{id:`cooking-233-05`,theoryId:233,type:`calculation`,difficulty:`intermediate`,safetyCritical:!1,question:{en:`A recipe has 960 kcal in total and yields four equal portions. How many kcal per portion?`,ua:`Рецепт має 960 ккал загалом і дає чотири однакові порції. Скільки ккал в одній порції?`},explanation:{en:`960 ÷ 4 = 240 kcal.`,ua:`960 ÷ 4 = 240 ккал.`},numericInput:{unit:`kcal`,unitLabel:{en:`kilocalories`,ua:`кілокалорій`},allowDecimals:!1},answer:{value:240,tolerance:0,unit:`kcal`}}];var n={theoryId:233,exercises:i};export{n as default,i as exercises,a as theoryId};